import sys

def h_brute(c):
    n = len(c)
    for h in range(n, -1, -1):
        if sum(1 for x in c if x >= h) >= h:
            return h
    return 0

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    c = list(map(int, data[1:1 + n]))
    print(h_brute(c))

import sys

def h_opt(c):
    c = sorted(c, reverse=True)
    h = 0
    for i, x in enumerate(c):
        if x >= i + 1:
            h = i + 1
        else:
            break
    return h

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    c = list(map(int, data[1:1 + n]))
    print(h_opt(c))

import sys

def h_best(c):
    n = len(c)
    max_c = max(c)
    cnt = [0] * (max_c + 1)
    for x in c:
        cnt[x] += 1
    s = 0
    for cite in range(max_c, -1, -1):
        s += cnt[cite]
        if s >= cite:
            return cite
    return 0

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    c = list(map(int, data[1:1 + n]))
    print(h_best(c))
